/**
 * Deterministic Unit Normalization Service.
 * Ensures that all clinical data fed into the Rules Engine (CDSS) uses standard units.
 * This prevents critical errors where "4.5 mmol/L" Lactate is misread as "4.5 mg/dL".
 */

export const NORMALIZED_UNITS = {
    GLUCOSE: 'mg/dL',
    CREATININE: 'mg/dL',
    LACTATE: 'mmol/L',
    POTASSIUM: 'mmol/L',
    TEMPERATURE: 'degC'
};

// Physiological Plausibility Limits (Hard Stops)
// Values outside these ranges are likely OCR errors, unit mismatches, or incompatibile with life.
// Based on typical adult ranges + pathology buffer.
export const PLAUSIBILITY_RANGES: Record<string, { min: number, max: number }> = {
    [NORMALIZED_UNITS.GLUCOSE]: { min: 10, max: 2000 }, // <10 is fatal, >2000 is syrup
    [NORMALIZED_UNITS.CREATININE]: { min: 0.1, max: 30.0 }, // >30 is extremely rare even in failure
    [NORMALIZED_UNITS.LACTATE]: { min: 0.1, max: 40.0 }, // Record is ~30-40
    [NORMALIZED_UNITS.POTASSIUM]: { min: 1.0, max: 12.0 }, // >12 is usually hemolyzed or error
    [NORMALIZED_UNITS.TEMPERATURE]: { min: 20.0, max: 46.5 } // <20 severe hypo, >46.5 protein denaturation
};

export interface NormalizedResult {
    value: number;
    unit: string;
    warning?: string; // If present, value is suspect
}

export const normalizeValue = (val: number, unit: string, testName: string): NormalizedResult => {
    const u = unit.toLowerCase().trim();
    const t = testName.toLowerCase();

    let resultValue = val;
    let resultUnit = unit;

    // --- CONVERSION LOGIC ---

    // GLUCOSE: Convert mmol/L to mg/dL (Standard: 1 mmol/L = 18.0182 mg/dL)
    if (t.includes('glucose')) {
        if (u === 'mmol/l' || u === 'mmol') {
            resultValue = parseFloat((val * 18.0182).toFixed(1));
            resultUnit = NORMALIZED_UNITS.GLUCOSE;
        } else if (u === 'mg/dl' || u === 'mg') {
            resultUnit = NORMALIZED_UNITS.GLUCOSE;
        }
    }

    // CREATININE: Convert umol/L to mg/dL (Standard: 88.4 umol/L = 1 mg/dL)
    else if (t.includes('creatinine') || t.includes('scr')) {
        if (u === 'umol/l' || u === 'µmol/l' || u === 'micromol/l') {
            resultValue = parseFloat((val / 88.4).toFixed(2));
            resultUnit = NORMALIZED_UNITS.CREATININE;
        } else if (u === 'mg/dl') {
            resultUnit = NORMALIZED_UNITS.CREATININE;
        }
    }

    // TEMPERATURE: Fahrenheit to Celsius
    else if (t.includes('temp')) {
        if (u === 'f' || u.includes('fahr')) {
            resultValue = parseFloat(((val - 32) * 5 / 9).toFixed(1));
            resultUnit = NORMALIZED_UNITS.TEMPERATURE;
        } else if (u === 'c' || u.includes('cels')) {
            resultUnit = NORMALIZED_UNITS.TEMPERATURE;
        }
    }

    // LACTATE: mg/dL to mmol/L (Standard: 1 mmol/L = 9.008 mg/dL)
    else if (t.includes('lactate')) {
        if (u === 'mg/dl') {
            resultValue = parseFloat((val / 9.008).toFixed(1));
            resultUnit = NORMALIZED_UNITS.LACTATE;
        } else {
            resultUnit = NORMALIZED_UNITS.LACTATE;
        }
    }

    // POTASSIUM: Usually mmol/L or mEq/L (1:1)
    else if (t.includes('potassium') || t.includes('k+')) {
        resultUnit = NORMALIZED_UNITS.POTASSIUM;
    }

    // --- PLAUSIBILITY CHECK LAYER ---
    // Validate the *normalized* value against hard limits

    const range = PLAUSIBILITY_RANGES[resultUnit];
    let warning: string | undefined;

    if (range) {
        if (resultValue < range.min) {
            warning = `IMPLAUSIBLE_LOW (Val: ${resultValue} < Min: ${range.min})`;
        } else if (resultValue > range.max) {
            warning = `IMPLAUSIBLE_HIGH (Val: ${resultValue} > Max: ${range.max})`;
        }
    }

    return { value: resultValue, unit: resultUnit, warning };
};

import { v4 as uuidv4 } from 'uuid';
import { FHIRObservation } from '../fhir/types';
import { CDSSAlert } from './types';
import { normalizeValue, NORMALIZED_UNITS } from '../fhir/unitService';

/**
 * DETERMINISTIC CLINICAL RULES ENGINE
 * 
 * This engine evaluates patient data against hard-coded, standard clinical protocols.
 * It does NOT use LLM inference for decision making, ensuring 100% predictable safety alerts.
 * 
 * Protocols Implemented:
 * 1. Sepsis-3 (Lactate, MAP)
 * 2. KDIGO AKI (Creatinine, Potassium)
 * 3. Vital Sign Instability (Tachycardia, Hypotension, Hypoxia)
 */

interface ClinicalValue {
    value: number;
    unit: string;
    timestamp: number;
}

const extractLatestValue = (observations: FHIRObservation[], matches: string[]): ClinicalValue | null => {
    const relevant = observations.filter(o => {
        const text = o.code.text?.toLowerCase() || '';
        return matches.some(m => text.includes(m));
    }).sort((a, b) => {
        const tA = a.effectiveDateTime ? new Date(a.effectiveDateTime).getTime() : 0;
        const tB = b.effectiveDateTime ? new Date(b.effectiveDateTime).getTime() : 0;
        return tB - tA;
    });

    if (relevant.length === 0) return null;
    const latest = relevant[0];

    if (latest.valueQuantity?.value !== undefined) {
        // NORMALIZE & VALIDATE
        const normalized = normalizeValue(
            latest.valueQuantity.value, 
            latest.valueQuantity.unit || '', 
            latest.code.text || ''
        );

        // SAFETY GATE: Ignore implausible values to prevent false alerts
        if (normalized.warning) {
            console.warn(`[CDSS] Skipped Implausible Value: ${latest.code.text} = ${normalized.value} ${normalized.unit} (${normalized.warning})`);
            return null;
        }

        return {
            value: normalized.value,
            unit: normalized.unit,
            timestamp: latest.effectiveDateTime ? new Date(latest.effectiveDateTime).getTime() : Date.now()
        };
    }
    return null;
};

export const evaluateClinicalSafety = async (observations: FHIRObservation[]): Promise<CDSSAlert[]> => {
    const alerts: CDSSAlert[] = [];
    const now = Date.now();

    // --- 1. SEPSIS-3 PROTOCOL ---
    // Trigger: Lactate > 4.0 mmol/L (Septic Shock Indicator)
    const lactate = extractLatestValue(observations, ['lactate']);
    if (lactate && lactate.unit === NORMALIZED_UNITS.LACTATE && lactate.value > 4.0) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-SEPSIS-3-LACTATE',
            title: 'CRITICAL: SEPTIC SHOCK CRITERIA',
            level: 'Critical',
            description: `Serum Lactate ${lactate.value} mmol/L exceeds critical threshold of 4.0 mmol/L. Consistent with Septic Shock.`,
            timestamp: now,
            triggers: [`Lactate: ${lactate.value} mmol/L`],
            actions: [
                { label: 'Order Fluid Bolus (30mL/kg)', type: 'order', payload: '30mL/kg Crystalloid Bolus' },
                { label: 'Order Vasopressors', type: 'order', payload: 'Norepinephrine' }
            ]
        });
    } else if (lactate && lactate.unit === NORMALIZED_UNITS.LACTATE && lactate.value >= 2.0) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-SEPSIS-3-WARNING',
            title: 'WARNING: ELEVATED LACTATE',
            level: 'Warning',
            description: `Serum Lactate ${lactate.value} mmol/L is elevated (>2.0). Monitor for sepsis progression.`,
            timestamp: now,
            triggers: [`Lactate: ${lactate.value} mmol/L`],
            actions: [{ label: 'Repeat Lactate in 2h', type: 'order', payload: 'Repeat Lactate Level' }]
        });
    }

    // --- 2. KDIGO AKI / ELECTROLYTE PROTOCOL ---
    // Trigger: Potassium > 6.0 (Critical Hyperkalemia)
    const potassium = extractLatestValue(observations, ['potassium', 'k+']);
    if (potassium && potassium.unit === NORMALIZED_UNITS.POTASSIUM && potassium.value > 6.0) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-ELECTROLYTE-K-CRIT',
            title: 'CRITICAL: HYPERKALEMIA',
            level: 'Critical',
            description: `Potassium ${potassium.value} mmol/L is critical (>6.0). Risk of cardiac arrhythmia.`,
            timestamp: now,
            triggers: [`K+: ${potassium.value} mmol/L`],
            actions: [
                { label: 'Order ECG', type: 'order', payload: '12-Lead ECG' },
                { label: 'Calcium Gluconate', type: 'order', payload: 'Calcium Gluconate 1g IV' }
            ]
        });
    }

    // Trigger: Creatinine > 4.0 (AKI Stage 3)
    const creatinine = extractLatestValue(observations, ['creatinine', 'scr']);
    if (creatinine && creatinine.unit === NORMALIZED_UNITS.CREATININE && creatinine.value > 4.0) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-KDIGO-AKI-3',
            title: 'CRITICAL: ACUTE KIDNEY INJURY',
            level: 'Critical',
            description: `Creatinine ${creatinine.value} mg/dL suggests KDIGO Stage 3 AKI.`,
            timestamp: now,
            triggers: [`Cr: ${creatinine.value} mg/dL`],
            actions: [{ label: 'Renal Consult', type: 'order', payload: 'Nephrology Consult' }]
        });
    }

    // --- 3. HEMODYNAMIC STABILITY ---
    // Trigger: MAP < 65 or SBP < 90 (Hypotension)
    const sbp = extractLatestValue(observations, ['systolic', 'sbp']);
    if (sbp && sbp.value < 90) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-HYPOTENSION',
            title: 'CRITICAL: HYPOTENSION',
            level: 'Critical',
            description: `Systolic BP ${sbp.value} mmHg is below critical threshold of 90 mmHg.`,
            timestamp: now,
            triggers: [`SBP: ${sbp.value} mmHg`],
            actions: [{ label: 'Assess Fluid Status', type: 'acknowledge' }]
        });
    }

    // Trigger: HR > 130 (Tachycardia)
    const hr = extractLatestValue(observations, ['heart rate', 'pulse', 'hr']);
    if (hr && hr.value > 130) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-TACHYCARDIA',
            title: 'WARNING: TACHYCARDIA',
            level: 'Warning',
            description: `Heart Rate ${hr.value} bpm is significantly elevated.`,
            timestamp: now,
            triggers: [`HR: ${hr.value} bpm`],
            actions: [{ label: 'Check Rhythm', type: 'order', payload: 'Telemetry Strip' }]
        });
    }

    // Trigger: SpO2 < 90% (Hypoxia)
    const spo2 = extractLatestValue(observations, ['spo2', 'oxygen', 'saturation']);
    if (spo2 && spo2.value < 90) {
        alerts.push({
            id: uuidv4(),
            ruleId: 'PROT-HYPOXIA',
            title: 'CRITICAL: HYPOXIA',
            level: 'Critical',
            description: `SpO2 ${spo2.value}% indicates respiratory compromise.`,
            timestamp: now,
            triggers: [`SpO2: ${spo2.value}%`],
            actions: [{ label: 'Titrate O2', type: 'acknowledge' }]
        });
    }

    return alerts;
};

import React, { useRef, useCallback, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { ChatMode as ChatModeEnum, UploadedFile, ChatMessage, GroundingSource } from '../../../types';
import { generateResponseStream } from '../../../services/geminiService';
import { exportBriefingToPdf } from '../../../services/exportService';
import { cleanJsonOutput, isJsonBriefing, getFriendlyErrorMessage, isLabReport, parseAndValidate } from '../../../utils';
import { FILE_ANALYSIS_PROMPT, BRIEFING_TRIGGERS, SHIFT_BRIEFING_PROMPT, HELP_COMMAND_RESPONSE, DRUG_ANALYSIS_PROMPT } from '../../../constants';
import { usePatientStore } from '../../patient-management/usePatientStore';
import { useChatStore } from '../stores/useChatStore';
import { useClinicalStore } from '../../clinical-analysis/stores/useClinicalStore';
import { useAuditStore } from '../../audit/useAuditStore';
import { useEntityExtractor } from '../../../hooks/useEntityExtractor';
import { FHIRObservation } from '../../fhir/types';
import { evaluateClinicalSafety } from '../../cdss/rulesEngine';
import { PatientMetadata } from '../../patient-management/types';
import { UIAction } from '../../ui/UIContext';
import { LabReportSchema, BriefingSchema, Briefing, LabReport } from '../schemas';
import { normalizeValue } from '../../fhir/unitService';

interface UseChatOrchestratorProps {
    messages: ChatMessage[];
    activePatientId: string;
    activePatient: PatientMetadata;
    chatMode: ChatModeEnum;
    uiDispatch: React.Dispatch<UIAction>;
    uploadedFile: UploadedFile | null;
    setUploadedFile: (file: UploadedFile | null) => void;
    isLive: boolean;
    stopSession: () => void;
    userLocation?: { latitude: number, longitude: number };
    clearFile: () => void;
}

export const useChatOrchestrator = ({
    messages,
    activePatientId,
    activePatient,
    chatMode,
    uiDispatch,
    uploadedFile,
    setUploadedFile,
    isLive,
    stopSession,
    userLocation,
    clearFile
}: UseChatOrchestratorProps) => {
    // Access actions from all stores
    const patientActions = usePatientStore(state => state.actions);
    const chatActions = useChatStore(state => state.actions);
    const clinicalActions = useClinicalStore(state => state.actions);
    const auditActions = useAuditStore(state => state.actions);

    const abortControllerRef = useRef<AbortController | null>(null);
    const { triggerExtraction } = useEntityExtractor();

    // Clean up on unmount
    useEffect(() => {
        return () => {
            if (abortControllerRef.current) {
                abortControllerRef.current.abort();
            }
        };
    }, []);

    const handleStop = useCallback(() => {
        if (abortControllerRef.current) abortControllerRef.current.abort();
        uiDispatch({ type: 'SET_LOADING', payload: false });
    }, [uiDispatch]);

    const handleClearChat = useCallback(() => {
        chatActions.resetChat(activePatientId);
        clearFile();
    }, [chatActions, activePatientId, clearFile]);

    const handleSend = useCallback(async (userPrompt: string) => {
        const trimmedPrompt = userPrompt.trim();
        if (!trimmedPrompt && !uploadedFile) return;

        if (isLive) {
            stopSession();
            uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Standard });
        }

        // Update last active
        patientActions.touchPatient(activePatientId);

        // --- Export Command ---
        if (trimmedPrompt.toLowerCase() === '/export') {
            const history = messages.filter(m => !isJsonBriefing(m.content));
            if (history.length === 0) {
                 chatActions.addMessage(activePatientId, { role: 'model', content: '⚠️ **Cannot Export:** No history available.' });
                 return;
            }

            chatActions.addMessage(activePatientId, { role: 'model', content: '📥 Generating briefing for PDF export...' });
            uiDispatch({ type: 'SET_LOADING', payload: true });

            abortControllerRef.current = new AbortController();
            try {
                const modeForRequest = ChatModeEnum.Standard;
                const stream = generateResponseStream(SHIFT_BRIEFING_PROMPT(), history, modeForRequest, { responseType: 'json' });
                let fullResponseText = '';
                for await (const chunk of stream) {
                    if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");
                    fullResponseText += chunk.text;
                }

                if (fullResponseText.includes("NO DATA")) throw new Error("Insufficient clinical data found.");

                // Use Zod validation for PDF export
                const parsedBriefing = parseAndValidate<Briefing>(fullResponseText, BriefingSchema);
                if (!parsedBriefing) throw new Error("Invalid briefing format generated by AI.");

                if (parsedBriefing.briefingTitle.includes("NO DATA")) throw new Error("Insufficient clinical data.");

                await exportBriefingToPdf(parsedBriefing);
                chatActions.updateLastMessageContent(activePatientId, '✅ Shift briefing PDF downloaded.');

                // Audit Export
                auditActions.logEvent(
                    'EXPORT_PDF', 
                    activePatientId, 
                    'Generated and downloaded shift briefing PDF', 
                    'USER',
                    { title: parsedBriefing.briefingTitle }
                );

            } catch (e) {
                if (e.message === "Aborted") {
                     chatActions.updateLastMessageContent(activePatientId, '🛑 Export cancelled.');
                } else {
                    const friendlyError = getFriendlyErrorMessage(e);
                    chatActions.updateLastMessageContent(activePatientId, `Sorry, PDF generation failed.\n\n**Reason:** ${friendlyError}`);
                }
            } finally {
                uiDispatch({ type: 'SET_LOADING', payload: false });
                abortControllerRef.current = null;
            }
            return;
        }

        // --- Help Command ---
        if (trimmedPrompt.toLowerCase() === '/help') {
             chatActions.addMessage(activePatientId, { role: 'user', content: '/help' });
             chatActions.addMessage(activePatientId, { role: 'model', content: HELP_COMMAND_RESPONSE });
             return;
        }

        // --- Standard Message & File Handling ---
        let finalApiPrompt = trimmedPrompt;
        let historyContent = trimmedPrompt;

        let fileForApi: UploadedFile | undefined = uploadedFile || undefined;

        let displayOverride = undefined;
        let modeForRequest: ChatModeEnum = chatMode === ChatModeEnum.Live ? ChatModeEnum.Standard : chatMode;
        let responseType: 'json' | 'text' = 'text';

        const isBriefingCommand = BRIEFING_TRIGGERS.some(trigger => trimmedPrompt.toLowerCase().includes(trigger)) || trimmedPrompt.toLowerCase() === '/brief';
        const isDrugCommand = trimmedPrompt.toLowerCase().startsWith('/drugs');

        if (uploadedFile) {
             if (activePatientId) {
                 // Trigger Safety Extraction
                 triggerExtraction(uploadedFile, activePatientId);

                 // Register Document (Lightweight Metadata Only)
                 if (uploadedFile.storageId) {
                     // We cast to any because we invoke the store action directly which is not fully typed in this hook's scope, 
                     // but the store knows the ADD_DOCUMENT action. 
                     // Ideally we'd expose this action via usePatientStore's return type interface.
                     // For now, assume the action exists on the store.
                     (usePatientStore.getState().actions as any).addDocument?.(activePatientId, {
                         storageId: uploadedFile.storageId,
                         name: uploadedFile.file.name,
                         type: uploadedFile.type,
                         uploadedAt: Date.now()
                     });
                 }
             }

             try {
                let analysisPrompt: string;
                if (uploadedFile.type === 'application/pdf') {
                    const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this medical document.`;
                    analysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name) + `\n\n${promptBase}`;
                } else if (uploadedFile.type === 'text/plain' || uploadedFile.file.name.endsWith('.txt') || uploadedFile.file.name.endsWith('.md')) {
                     const textContent = await uploadedFile.file.text();
                     const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this document.`;
                     const fullEmbeddedContent = `*** BEGIN FILE CONTENT: ${uploadedFile.file.name} ***\n${textContent}\n*** END FILE CONTENT ***\n\n${promptBase}`;
                     analysisPrompt = fullEmbeddedContent;
                     historyContent = fullEmbeddedContent;
                     displayOverride = `📄 **Uploaded ${uploadedFile.file.name}**\n\n${trimmedPrompt || "Requested analysis."}`;
                     fileForApi = undefined; 
                } else {
                    const baseAnalysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name);
                    if (!trimmedPrompt) {
                        analysisPrompt = baseAnalysisPrompt;
                        displayOverride = `Analyzing file: ${uploadedFile.file.name}`; 
                    } else {
                        analysisPrompt = `${baseAnalysisPrompt}\n\n---\n**ADDITIONAL INSTRUCTION:**\nThe user has asked: "${trimmedPrompt}".\n1. You MUST still output VALID JSON.\n2. Answer the user's question within the "visualObservations" or "note" fields.`;
                    }
                }

                finalApiPrompt = analysisPrompt;
                if (isBriefingCommand) {
                    finalApiPrompt = `${finalApiPrompt}\n\nIMPORTANT: After analyzing, ${SHIFT_BRIEFING_PROMPT()}`;
                    modeForRequest = ChatModeEnum.Standard;
                    responseType = 'json';
                    if (!displayOverride) historyContent = trimmedPrompt || "/brief (with file)";
                }
             } catch (error) {
                 chatActions.addMessage(activePatientId, { role: 'model', content: `Error: ${getFriendlyErrorMessage(error)}` });
                 uiDispatch({ type: 'SET_ERROR', payload: getFriendlyErrorMessage(error) });
                 return;
             }
        } else if (isBriefingCommand) {
            finalApiPrompt = SHIFT_BRIEFING_PROMPT();
            historyContent = "/brief"; 
            modeForRequest = ChatModeEnum.Standard;
            responseType = 'json';

            // Log Briefing Request
            auditActions.logEvent('BRIEFING_GENERATED', activePatientId, 'Briefing requested via command', 'USER');

        } else if (isDrugCommand) {
            finalApiPrompt = DRUG_ANALYSIS_PROMPT(trimmedPrompt);
            modeForRequest = ChatModeEnum.Standard; 
            responseType = 'json';
        }

        if (trimmedPrompt.toLowerCase().startsWith('/patient')) modeForRequest = ChatModeEnum.Standard;

        const userMessage: ChatMessage = { role: 'user', content: historyContent };
        if (displayOverride) userMessage.displayContent = displayOverride;

        if (uploadedFile && fileForApi) { 
            userMessage.filePreview = { 
                name: uploadedFile.file.name, 
                type: uploadedFile.type, 
                url: uploadedFile.url,
                storageId: uploadedFile.storageId 
            };
        }

        chatActions.addMessage(activePatientId, userMessage);
        chatActions.addResponsePlaceholder(activePatientId);
        uiDispatch({ type: 'SET_LOADING', payload: true });
        uiDispatch({ type: 'SET_ERROR', payload: null });
        setUploadedFile(null);

        abortControllerRef.current = new AbortController();
        let fullResponseBuffer = '';

        try {
            const history = [...messages];
            const stream = generateResponseStream(finalApiPrompt, history, modeForRequest, { file: fileForApi, responseType, location: userLocation });

            for await (const chunk of stream) {
                if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");

                const textChunk = chunk.text || '';
                fullResponseBuffer += textChunk;

                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                let sources: GroundingSource[] | undefined = undefined;

                if (groundingMetadata && groundingMetadata.groundingChunks) {
                    sources = groundingMetadata.groundingChunks.map(chunk => {
                        if (chunk.web) return { web: chunk.web };
                        if ((chunk as any).maps) return { maps: (chunk as any).maps };
                        return undefined;
                    }).filter(Boolean) as GroundingSource[];
                }

                chatActions.appendToLastMessage(activePatientId, textChunk, sources);
            }
        } catch (e) {
             if (e.message === "Aborted") {
                 chatActions.appendToLastMessage(activePatientId, " [Stopped]", undefined);
            } else {
                const errorMsg = `Sorry, I encountered an error.\n\n**Details:** ${getFriendlyErrorMessage(e)}`;
                chatActions.updateLastMessageContent(activePatientId, errorMsg);
            }
        } finally {
            uiDispatch({ type: 'SET_LOADING', payload: false });

            // --- FHIR AUTO-INGESTION PROTOCOL WITH ZOD & UNIT NORMALIZATION & PLAUSIBILITY CHECK ---
            if (activePatientId && isLabReport(fullResponseBuffer)) {
                // Use generic to validate and infer LabReport type
                const report = parseAndValidate<LabReport>(fullResponseBuffer, LabReportSchema);

                if (report && report.labs) {
                    const newObs: FHIRObservation[] = report.labs.map((lab: any) => {
                         const rawVal = parseFloat(lab.value.replace(/[^0-9.-]/g, ''));
                         const rangeMatch = lab.refRange.match(/([\d.]+)\s*-\s*([\d.]+)/);

                         if (isNaN(rawVal)) return null;

                         // SAFETY: Normalize units to prevent CDSS errors
                         // Uses the centralized service for deterministic conversion + PLAUSIBILITY CHECK
                         const normalized = normalizeValue(rawVal, lab.units, lab.testName);

                         const obs: FHIRObservation = {
                             resourceType: 'Observation',
                             id: uuidv4(),
                             status: 'final',
                             code: { 
                                 text: lab.testName 
                             },
                             subject: { reference: `Patient/${activePatientId}` },
                             valueQuantity: { 
                                 value: normalized.value, 
                                 unit: normalized.unit,
                                 system: 'http://unitsofmeasure.org'
                             },
                             effectiveDateTime: report.date && report.date !== 'Not Visible' ? new Date(report.date).toISOString() : new Date().toISOString(),
                             issued: new Date().toISOString()
                         };

                         // ATTACH DATA QUALITY WARNING IF DETECTED
                         if (normalized.warning) {
                             obs.note = [{ text: `⚠️ DATA QUALITY: ${normalized.warning}` }];
                             // Flag interpretation so TrendGraph can potentially filter it
                             obs.interpretation = [{ text: 'Data Quality Issue' }];
                         } else if (lab.flag && lab.flag !== 'Normal') {
                             obs.interpretation = [{ text: lab.flag }];
                         }

                         if (rangeMatch) {
                             obs.referenceRange = [{
                                 low: { value: parseFloat(rangeMatch[1]), unit: lab.units, system: 'http://unitsofmeasure.org' },
                                 high: { value: parseFloat(rangeMatch[2]), unit: lab.units, system: 'http://unitsofmeasure.org' },
                                 text: lab.refRange
                             }];
                         }

                         return obs;
                    }).filter(Boolean);

                    if (newObs.length > 0) {
                        clinicalActions.ingestObservations(activePatientId, newObs);

                        const existingObs = useClinicalStore.getState().data[activePatientId]?.observations || [];
                        const combinedObs = [...existingObs, ...newObs];

                        // Use the NEW Deterministic Rules Engine (No await needed technically, but good for future async)
                        evaluateClinicalSafety(combinedObs).then(alerts => {
                            if (alerts.length > 0) {
                                clinicalActions.updateAlerts(activePatientId, alerts);

                                // Audit Alert Trigger
                                auditActions.logEvent(
                                    'ALERT_TRIGGERED', 
                                    activePatientId, 
                                    `Generated ${alerts.length} safety alerts from lab data`, 
                                    'SYSTEM'
                                );
                            }
                        });
                    }
                } else {
                    console.warn("Lab report detected but failed validation.");
                }
            }

            abortControllerRef.current = null;
        }
    }, [messages, activePatientId, chatMode, uploadedFile, isLive, stopSession, userLocation, patientActions, chatActions, clinicalActions, auditActions, uiDispatch, setUploadedFile, triggerExtraction]);

    return {
        handleSend,
        handleStop,
        handleClearChat,
        handleExportChat: useCallback(() => handleSend('/export'), [handleSend])
    };
};

import React from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid, ResponsiveContainer, ReferenceArea } from 'recharts';
import { FHIRObservation } from '../fhir/types';

interface TrendGraphProps {
    testName: string;
    observations: FHIRObservation[];
}

const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
        return (
            <div className="bg-slate-900 text-white p-2 rounded-sm border border-slate-700 text-xs shadow-xl">
                <p className="font-mono mb-1 text-slate-400">{label}</p>
                <p className="font-bold text-sm">
                    {payload[0].value} {payload[0].unit}
                </p>
            </div>
        );
    }
    return null;
};

const TrendGraph: React.FC<TrendGraphProps> = ({ testName, observations }) => {
    // Filter and Sort Data
    const data = observations
        .filter(o => 
            o.code.text === testName && 
            o.valueQuantity && 
            o.valueQuantity.value !== undefined &&
            // EXCLUDE DATA QUALITY ISSUES (IMPLAUSIBLE VALUES)
            // If the note contains "DATA QUALITY", it was flagged by unitService as an OCR/Unit error.
            !o.note?.some(n => n.text.includes('DATA QUALITY'))
        )
        .map(o => ({
            date: o.effectiveDateTime ? new Date(o.effectiveDateTime).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : 'Unknown',
            fullDate: o.effectiveDateTime ? new Date(o.effectiveDateTime).toLocaleString() : 'Unknown',
            value: o.valueQuantity!.value,
            unit: o.valueQuantity!.unit || '',
            low: o.referenceRange?.[0]?.low?.value,
            high: o.referenceRange?.[0]?.high?.value,
            timestamp: o.effectiveDateTime ? new Date(o.effectiveDateTime).getTime() : 0
        }))
        .sort((a, b) => a.timestamp - b.timestamp);

    if (data.length < 2) return null;

    // Get range from the last observation (assuming consistency)
    const refLow = data[data.length - 1].low;
    const refHigh = data[data.length - 1].high;

    return (
        <div className="w-full h-[180px] bg-white dark:bg-slate-900/50 rounded-sm border border-slate-200 dark:border-slate-800 p-2 mt-4 relative">
             <div className="absolute top-2 left-3 z-10">
                <h4 className="text-[10px] font-mono font-bold uppercase tracking-widest text-slate-500">
                    Trend Analysis: {testName}
                </h4>
            </div>

            <ResponsiveContainer width="100%" height="100%">
                <LineChart data={data} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" opacity={0.2} />

                    <XAxis 
                        dataKey="date" 
                        tick={{ fontSize: 9, fill: '#64748b' }} 
                        axisLine={false}
                        tickLine={false}
                    />
                    <YAxis 
                        domain={['auto', 'auto']} 
                        tick={{ fontSize: 9, fill: '#64748b' }} 
                        axisLine={false}
                        tickLine={false}
                    />

                    <Tooltip content={<CustomTooltip />} />

                    {/* Reference Range Shading */}
                    {refLow !== undefined && refHigh !== undefined && (
                         <ReferenceArea 
                            y1={refLow} 
                            y2={refHigh} 
                            fill="#22c55e" 
                            fillOpacity={0.05} 
                        />
                    )}

                    <Line 
                        type="monotone" 
                        dataKey="value" 
                        stroke="#3b82f6" 
                        strokeWidth={2}
                        dot={{ r: 3, fill: '#3b82f6', strokeWidth: 0 }}
                        activeDot={{ r: 5, fill: '#60a5fa' }}
                        animationDuration={1000}
                    />
                </LineChart>
            </ResponsiveContainer>
        </div>
    );
};

